// ============================================
// DATABASE INITIALIZATION
// ============================================

// Composio sessions keyed by workspace ID (for isolation)
const composioSessions = new Map<string, { mcp: { url: string; headers: Record<string, string> } }>();
let defaultComposioSession: { mcp: { url: string; headers: Record<string, string> } } | null = null;
let composioClient: Composio | null = null;

function getComposioClient(): Composio {
  if (!composioClient) {
    composioClient = new Composio();
  }
  return composioClient;
}

async function initializeComposioSession() {
  console.log('[COMPOSIO] Pre-initializing default session...');
  try {
    const composio = getComposioClient();
    // eslint-disable-next-line @typescript-eslint/no-explicit-any
    const session = await composio.create('default-user') as any;
    defaultComposioSession = {
      mcp: {
        url: session.mcp?.url || '',
        headers: session.mcp?.headers || {}
      }
    };
    console.log('[COMPOSIO] Default session ready with MCP URL:', defaultComposioSession.mcp.url);

    // Update opencode.json with the MCP config
    updateOpencodeConfig(defaultComposioSession.mcp.url, defaultComposioSession.mcp.headers);
    console.log('[OPENCODE] Updated opencode.json with MCP config');
  } catch (error) {
    console.error('[COMPOSIO] Failed to pre-initialize session:', (error as Error).message);
  }
}

/**
 * Get or create a Composio session for a specific workspace
 * This ensures integrations are isolated per workspace
 */
async function getOrCreateWorkspaceSession(workspaceId: string, userId: string) {
  // Check for cached session
  const cached = composioSessions.get(workspaceId);
  if (cached) {
    return cached;
  }

  // Create workspace-specific entity ID for isolation
  const entityId = `ws_${workspaceId}_user_${userId}`;
  console.log('[COMPOSIO] Creating session for entity:', entityId);

  try {
    const composio = getComposioClient();
    // eslint-disable-next-line @typescript-eslint/no-explicit-any
    const session = await composio.create(entityId, { manageConnections: true }) as any;

    const workspaceSession = {
      mcp: {
        url: session.mcp?.url || '',
        headers: session.mcp?.headers || {}
      }
    };

    // Cache the session
    composioSessions.set(workspaceId, workspaceSession);
    console.log('[COMPOSIO] Created workspace session, MCP URL:', workspaceSession.mcp.url);

    return workspaceSession;
  } catch (error) {
    console.error('[COMPOSIO] Failed to create workspace session:', (error as Error).message);
    // Fallback to default session
    return defaultComposioSession;
  }
}

function updateOpencodeConfig(mcpUrl: string, mcpHeaders: Record<string, string>) {
  const opencodeConfigPath = path.join(__dirname, 'opencode.json');
  const config = {
    mcp: {
      composio: {
        type: 'remote',
        url: mcpUrl,
        headers: mcpHeaders
      }
    }
  };
  fs.writeFileSync(opencodeConfigPath, JSON.stringify(config, null, 2));
}

async function getComposioSession(_userId: string) {
  return { composioSessions, defaultComposioSession, updateOpencodeConfig, getOrCreateWorkspaceSession };
}

async function startServer() {
  try {
    // Initialize database
    console.log('[DB] Connecting to database...');
    await initializeDatabase();

    // Setup vector support for embeddings
    await setupVectorSupport();
    console.log('[DB] Database initialized');

    // Initialize providers
    await initializeProviders();

    // Initialize Composio session
    await initializeComposioSession();

    // Start server
    const server = app.listen(PORT, () => {
      console.log(`\n✓ Backend server running on http://localhost:${PORT}`);
      console.log(`✓ Health check: GET http://localhost:${PORT}/api/health`);
      console.log(`✓ Auth: POST http://localhost:${PORT}/api/auth/register`);
      console.log(`✓ Auth: POST http://localhost:${PORT}/api/auth/login`);
      console.log(`✓ Workspaces: http://localhost:${PORT}/api/workspaces`);
      console.log(`✓ Chats: http://localhost:${PORT}/api/chats`);
      console.log(`✓ Available providers: ${getAvailableProviders().join(', ')}\n`);
    });

    // Keep the process alive
    server.on('error', (err) => {
      console.error('Server error:', err);
    });

    // Graceful shutdown
    process.on('SIGINT', async () => {
      console.log('\nShutting down server...');
      server.close(async () => {
        await closeDb();
        console.log('Server closed');
        process.exit(0);
      });
    });

  } catch (error) {
    console.error('[STARTUP] Error:', error);
    process.exit(1);
  }
}

startServer();

/**
 * Base provider interface for AI agent providers.
 * All providers must implement these methods.
 */

import type { StreamChunk } from '@normie/types';

/**
 * Parameters for provider query method
 */
export interface QueryParams {
  /** The current user message */
  prompt: string;
  /** Conversation history with current message */
  messages: Array<{ role: string; content: string }>;
  /** System prompt from workspace context */
  systemPrompt?: string;
  /** Chat session identifier */
  chatId: string;
  /** Existing session ID from DB (for resumption) */
  sessionId?: string;
  /** User identifier */
  userId: string;
  /** MCP server configurations */
  mcpServers?: Record<string, unknown>;
  /** List of allowed tool names */
  allowedTools?: string[];
  /** Maximum conversation turns */
  maxTurns?: number;
  /** Model to use */
  model?: string;
}

/**
 * Provider configuration object
 */
export interface ProviderConfig {
  [key: string]: unknown;
}

/**
 * Message format for conversation history
 */
export interface HistoryMessage {
  role: 'user' | 'assistant';
  content: string;
}

/**
 * Base provider abstract class for AI agent providers.
 * All providers must extend this class and implement the abstract methods.
 */
export abstract class BaseProvider {
  protected config: ProviderConfig;
  protected sessions: Map<string, string>;

  constructor(config: ProviderConfig = {}) {
    this.config = config;
    this.sessions = new Map();
  }

  /**
   * Get the provider name
   */
  abstract get name(): string;

  /**
   * Initialize the provider
   */
  abstract initialize(): Promise<void>;

  /**
   * Execute a query/prompt and yield streaming responses
   * @param params - Query parameters
   * @yields Streaming response chunks
   */
  abstract query(params: QueryParams): AsyncGenerator<StreamChunk>;

  /**
   * Build a prompt string from messages array (for providers that don't support native history)
   * @param messages - Conversation history
   * @param systemPrompt - Optional system prompt
   * @returns Formatted prompt string
   */
  protected buildPromptFromHistory(
    messages: HistoryMessage[],
    systemPrompt?: string | null
  ): string {
    const parts: string[] = [];

    if (systemPrompt) {
      parts.push(systemPrompt);
      parts.push('---');
    }

    for (const msg of messages) {
      if (msg.role === 'user') {
        parts.push(`User: ${msg.content}`);
      } else if (msg.role === 'assistant') {
        parts.push(`Assistant: ${msg.content}`);
      }
    }

    return parts.join('\n\n');
  }

  /**
   * Get or create a session for a chat
   * @param chatId - Chat identifier
   * @returns Session ID if exists, null otherwise
   */
  getSession(chatId: string): string | null {
    return this.sessions.get(chatId) || null;
  }

  /**
   * Store a session ID for a chat
   * @param chatId - Chat identifier
   * @param sessionId - Session identifier to store
   */
  setSession(chatId: string, sessionId: string): void {
    this.sessions.set(chatId, sessionId);
  }

  /**
   * Abort an active query for a given chatId
   * @param chatId - Chat identifier
   * @returns True if aborted, false if no active query
   */
  abort(_chatId: string): boolean {
    // Override in subclass to implement abort functionality
    return false;
  }

  /**
   * Cleanup resources
   */
  async cleanup(): Promise<void> {
    this.sessions.clear();
  }
}

import { Router, Request, Response } from 'express';
import { eq, and, desc } from 'drizzle-orm';
import { requireAuth, requireWorkspaceAccess } from '../auth/index.js';
import { getDb } from '../db/index.js';
import * as schema from '../db/schema.js';

const router = Router();

router.use(requireAuth);

// Request body types
interface CreateChatBody {
  title?: string;
  provider?: string;
  model?: string;
}

interface UpdateChatBody {
  title?: string;
  model?: string;
}

interface UpdateSessionBody {
  sessionId?: string;
  sessionProvider?: string;
}

interface AddMessageBody {
  role: string;
  content: string;
  metadata?: Record<string, unknown>;
}

// ============================================
// LIST CHATS
// ============================================
router.get('/workspace/:workspaceId', requireWorkspaceAccess, async (req: Request, res: Response) => {
  try {
    const workspaceId = req.params.workspaceId as string;
    const db = getDb();
    const chatsList = await db.select({
      id: schema.chats.id,
      title: schema.chats.title,
      provider: schema.chats.provider,
      model: schema.chats.model,
      sessionId: schema.chats.sessionId,
      sessionProvider: schema.chats.sessionProvider,
      createdAt: schema.chats.createdAt,
      updatedAt: schema.chats.updatedAt
    })
      .from(schema.chats)
      .where(eq(schema.chats.workspaceId, workspaceId))
      .orderBy(desc(schema.chats.updatedAt));

    res.json({ chats: chatsList });
  } catch (err) {
    console.error('[CHAT] List error:', err);
    res.status(500).json({ error: 'Failed to list chats' });
  }
});

// ============================================
// CREATE CHAT
// ============================================
router.post('/workspace/:workspaceId', requireWorkspaceAccess, async (req: Request, res: Response) => {
  if (req.workspaceRole === 'viewer') {
    return res.status(403).json({ error: 'Viewers cannot create chats' });
  }

  try {
    const workspaceId = req.params.workspaceId as string;
    const { title, provider = 'claude', model } = req.body as CreateChatBody;
    const db = getDb();

    const [chat] = await db.insert(schema.chats)
      .values({
        workspaceId,
        userId: req.userId!,
        title: title || 'New Chat',
        provider,
        model: model || null
      })
      .returning({
        id: schema.chats.id,
        title: schema.chats.title,
        provider: schema.chats.provider,
        model: schema.chats.model,
        sessionId: schema.chats.sessionId,
        sessionProvider: schema.chats.sessionProvider,
        createdAt: schema.chats.createdAt
      });

    res.json(chat);
  } catch (err) {
    console.error('[CHAT] Create error:', err);
    res.status(500).json({ error: 'Failed to create chat' });
  }
});

// ============================================
// GET CHAT WITH MESSAGES
// ============================================
router.get('/:chatId', async (req: Request, res: Response) => {
  try {
    const chatId = req.params.chatId as string;
    const db = getDb();

    // Get chat
    const [chat] = await db.select()
      .from(schema.chats)
      .where(eq(schema.chats.id, chatId));

    if (!chat) {
      return res.status(404).json({ error: 'Chat not found' });
    }

    // Verify workspace access
    const [workspace] = await db.select()
      .from(schema.workspaces)
      .where(eq(schema.workspaces.id, chat.workspaceId));

    const isOwner = workspace.ownerId === req.userId;

    if (!isOwner) {
      const [membership] = await db.select()
        .from(schema.workspaceMembers)
        .where(and(
          eq(schema.workspaceMembers.workspaceId, workspace.id),
          eq(schema.workspaceMembers.userId, req.userId!)
        ));

      if (!membership) {
        return res.status(403).json({ error: 'Access denied' });
      }
    }

    // Get messages
    const messages = await db.select()
      .from(schema.messages)
      .where(eq(schema.messages.chatId, chat.id))
      .orderBy(schema.messages.createdAt);

    res.json({ ...chat, messages });
  } catch (err) {
    console.error('[CHAT] Get error:', err);
    res.status(500).json({ error: 'Failed to get chat' });
  }
});

// ============================================
// UPDATE CHAT
// ============================================
router.patch('/:chatId', async (req: Request, res: Response) => {
  try {
    const chatId = req.params.chatId as string;
    const { title, model } = req.body as UpdateChatBody;
    const db = getDb();

    // Get chat and verify ownership
    const [chat] = await db.select()
      .from(schema.chats)
      .where(eq(schema.chats.id, chatId));

    if (!chat) {
      return res.status(404).json({ error: 'Chat not found' });
    }

    // Verify access
    const [workspace] = await db.select()
      .from(schema.workspaces)
      .where(eq(schema.workspaces.id, chat.workspaceId));

    if (workspace.ownerId !== req.userId) {
      const [membership] = await db.select()
        .from(schema.workspaceMembers)
        .where(and(
          eq(schema.workspaceMembers.workspaceId, workspace.id),
          eq(schema.workspaceMembers.userId, req.userId!)
        ));

      if (!membership || membership.role === 'viewer') {
        return res.status(403).json({ error: 'Access denied' });
      }
    }

    const [updated] = await db.update(schema.chats)
      .set({ title, model, updatedAt: new Date() })
      .where(eq(schema.chats.id, chat.id))
      .returning({
        id: schema.chats.id,
        title: schema.chats.title,
        model: schema.chats.model
      });

    res.json(updated);
  } catch (err) {
    console.error('[CHAT] Update error:', err);
    res.status(500).json({ error: 'Failed to update chat' });
  }
});

// ============================================
// UPDATE CHAT SESSION
// ============================================
router.patch('/:chatId/session', async (req: Request, res: Response) => {
  try {
    const chatId = req.params.chatId as string;
    const { sessionId, sessionProvider } = req.body as UpdateSessionBody;
    const db = getDb();

    // Get chat and verify ownership
    const [chat] = await db.select()
      .from(schema.chats)
      .where(eq(schema.chats.id, chatId));

    if (!chat) {
      return res.status(404).json({ error: 'Chat not found' });
    }

    // Verify access
    const [workspace] = await db.select()
      .from(schema.workspaces)
      .where(eq(schema.workspaces.id, chat.workspaceId));

    if (workspace.ownerId !== req.userId) {
      const [membership] = await db.select()
        .from(schema.workspaceMembers)
        .where(and(
          eq(schema.workspaceMembers.workspaceId, workspace.id),
          eq(schema.workspaceMembers.userId, req.userId!)
        ));

      if (!membership) {
        return res.status(403).json({ error: 'Access denied' });
      }
    }

    const [updated] = await db.update(schema.chats)
      .set({ 
        sessionId, 
        sessionProvider,
        updatedAt: new Date() 
      })
      .where(eq(schema.chats.id, chat.id))
      .returning({
        id: schema.chats.id,
        sessionId: schema.chats.sessionId,
        sessionProvider: schema.chats.sessionProvider
      });

    res.json(updated);
  } catch (err) {
    console.error('[CHAT] Update session error:', err);
    res.status(500).json({ error: 'Failed to update session' });
  }
});

// ============================================
// DELETE CHAT
// ============================================
router.delete('/:chatId', async (req: Request, res: Response) => {
  try {
    const chatId = req.params.chatId as string;
    const db = getDb();

    // Get chat and verify ownership
    const [chat] = await db.select()
      .from(schema.chats)
      .where(eq(schema.chats.id, chatId));

    if (!chat) {
      return res.status(404).json({ error: 'Chat not found' });
    }

    // Verify access
    const [workspace] = await db.select()
      .from(schema.workspaces)
      .where(eq(schema.workspaces.id, chat.workspaceId));

    if (workspace.ownerId !== req.userId) {
      const [membership] = await db.select()
        .from(schema.workspaceMembers)
        .where(and(
          eq(schema.workspaceMembers.workspaceId, workspace.id),
          eq(schema.workspaceMembers.userId, req.userId!)
        ));
      if (!membership || membership.role === 'viewer') {
        return res.status(403).json({ error: 'Access denied' });
      }
    }

    await db.delete(schema.chats)
      .where(eq(schema.chats.id, chat.id));

    res.json({ success: true });
  } catch (err) {
    console.error('[CHAT] Delete error:', err);
    res.status(500).json({ error: 'Failed to delete chat' });
  }
});

// ============================================
// ADD MESSAGE
// ============================================
router.post('/:chatId/messages', async (req: Request, res: Response) => {
  try {
    const chatId = req.params.chatId as string;
    const { role, content, metadata } = req.body as AddMessageBody;

    if (!role || !content) {
      return res.status(400).json({ error: 'Role and content required' });
    }

    const db = getDb();

    // Get chat and verify access
    const [chat] = await db.select()
      .from(schema.chats)
      .where(eq(schema.chats.id, chatId));

    if (!chat) {
      return res.status(404).json({ error: 'Chat not found' });
    }

    // Verify access
    const [workspace] = await db.select()
      .from(schema.workspaces)
      .where(eq(schema.workspaces.id, chat.workspaceId));

    if (workspace.ownerId !== req.userId) {
      const [membership] = await db.select()
        .from(schema.workspaceMembers)
        .where(and(
          eq(schema.workspaceMembers.workspaceId, workspace.id),
          eq(schema.workspaceMembers.userId, req.userId!)
        ));
      if (!membership || membership.role === 'viewer') {
        return res.status(403).json({ error: 'Access denied' });
      }
    }

    const [message] = await db.insert(schema.messages)
      .values({
        chatId: chat.id,
        role,
        content,
        metadata: metadata || {}
      })
      .returning({
        id: schema.messages.id,
        role: schema.messages.role,
        content: schema.messages.content,
        metadata: schema.messages.metadata,
        createdAt: schema.messages.createdAt
      });

    // Update chat updatedAt
    await db.update(schema.chats)
      .set({ updatedAt: new Date() })
      .where(eq(schema.chats.id, chat.id));

    res.json(message);
  } catch (err) {
    console.error('[CHAT] Add message error:', err);
    res.status(500).json({ error: 'Failed to add message' });
  }
});

export default router;

