## Implementation Plan: Fix Chat Switching Slowness

### Current Problem Analysis

The current flow has these issues:

1. **Blocking `isLoading` state** (`useChatActions.ts:11,29,73`): When `loadChat` is called, it sets `isLoading = true` immediately, blocking the UI
2. **Manual API call**: Instead of using TanStack Query's `useChatDetail`, it manually calls `chatApi.get()` and waits for completion
3. **Cache check happens before state update**: The cached chat check returns early but still after a React render cycle
4. **No immediate feedback**: User clicks → wait for check → UI updates → API call → UI updates again

The key insight is that **`useChatDetail` already exists** in `useChats.ts:44-58` but is NOT being used in `ChatContext`. Instead, `useChatActions` manages its own state with `useState` and manual API calls.

### Desired New Flow

```
User clicks chat in sidebar
         ↓
Instantly update URL/state (immediate visual feedback)
         ↓
TanStack Query returns cached data (or skeleton if none)
         ↓
Background refetch (if stale)
         ↓
UI updates seamlessly when fresh data arrives
```

---

## Step-by-Step Implementation

### Phase 1: Create `useCurrentChat` Hook (NEW)

**File: `apps/web/src/hooks/useCurrentChat.ts`**

Create a new hook that uses TanStack Query's `useChatDetail` for data fetching:

```typescript
/**
 * useCurrentChat - TanStack Query-powered chat loading
 * 
 * Replaces the manual loading in useChatActions with TanStack Query.
 * Provides instant cached data + background refetching.
 */
import { useQuery, useQueryClient } from '@tanstack/react-query';
import { useCallback, useEffect } from 'react';
import type { Chat } from '@normie/types';
import { chatApi } from '@/lib/api';
import { chatKeys } from './useChats';
import { getCurrentChatId, setCurrentChatId } from '@/lib/storage';

interface UseCurrentChatParams {
  workspaceId: string | undefined;
  chatId: string | null;
  enabled: boolean;
}

export function useCurrentChat(params: UseCurrentChatParams) {
  const { workspaceId, chatId, enabled } = params;
  const queryClient = useQueryClient();

  // Query for chat details with messages
  const {
    data: chat,
    isLoading: isLoadingChat,
    isFetching: isFetchingChat,
    error,
  } = useQuery({
    queryKey: chatKeys.detail(chatId!),
    queryFn: async (): Promise<Chat | null> => {
      if (!chatId) return null;
      const chatData = await chatApi.get(chatId);
      return chatData as Chat;
    },
    enabled: enabled && !!chatId,
    staleTime: 5 * 60 * 1000, // 5 minutes - chat data doesn't change often
  });

  // Set currentChatId in localStorage when chat changes
  useEffect(() => {
    if (chatId) {
      setCurrentChatId(chatId);
    }
  }, [chatId]);

  // Prefetch neighboring chats (next/prev in list)
  const prefetchChat = useCallback(
    (id: string) => {
      if (!id) return;
      queryClient.prefetchQuery({
        queryKey: chatKeys.detail(id),
        queryFn: () => chatApi.get(id),
        staleTime: 5 * 60 * 1000,
      });
    },
    [queryClient]
  );

  return {
    chat,
    isLoading: isLoadingChat, // True only on first load (no cache)
    isFetching: isFetchingChat, // True during any fetch (including background)
    error,
    prefetchChat,
  };
}
```

### Phase 2: Create `useChatNavigation` Hook (NEW)

**File: `apps/web/src/hooks/useChatNavigation.ts`**

Replaces `useChatActions` for navigation only (not loading):

```typescript
/**
 * useChatNavigation - Navigation without data loading
 * 
 * Manages which chat is "current" without blocking on data loading.
 * Data loading is handled separately by useCurrentChat via TanStack Query.
 */
import { useCallback, useState } from 'react';
import { useQueryClient } from '@tanstack/react-query';
import { chatKeys } from './useChats';
import { setCurrentChatId } from '@/lib/storage';

interface UseChatNavigationReturn {
  currentChatId: string | null;
  navigateToChat: (chatId: string) => void;
  navigateToNewChat: () => void;
}

export function useChatNavigation(): UseChatNavigationReturn {
  const queryClient = useQueryClient();
  const [currentChatId, setCurrentChatIdState] = useState<string | null>(null);

  const navigateToChat = useCallback((chatId: string) => {
    // Instant - no waiting
    setCurrentChatIdState(chatId);
    setCurrentChatId(chatId);

    // Prefetch for instant feel
    queryClient.prefetchQuery({
      queryKey: chatKeys.detail(chatId),
      queryFn: async () => {
        const { chatApi } = await import('@/lib/api');
        return chatApi.get(chatId);
      },
      staleTime: 5 * 60 * 1000,
    });
  }, [queryClient]);

  const navigateToNewChat = useCallback(() => {
    setCurrentChatIdState(null);
    setCurrentChatId(null);
  }, []);

  return {
    currentChatId,
    navigateToChat,
    navigateToNewChat,
  };
}
```

