/**
 * Tool icon mapping and categorization
 *
 * Maps tool names to appropriate icons and categories for better UX.
 */
import {
  FileText,
  FilePlus,
  FileEdit,
  Terminal,
  Search,
  Globe,
  FolderOpen,
  Image,
  Database,
  Mail,
  Calendar,
  MessageSquare,
  Code,
  Wrench,
  type LucideIcon,
} from 'lucide-react';

export type ToolCategory = 
  | 'file' 
  | 'shell' 
  | 'search' 
  | 'browser' 
  | 'communication' 
  | 'data' 
  | 'utility'
  | 'unknown';

export interface ToolMeta {
  icon: LucideIcon;
  category: ToolCategory;
  label: string;
}

// Tool name patterns to meta mapping
const toolPatterns: Array<{
  pattern: RegExp;
  meta: ToolMeta;
}> = [
  // File operations
  { pattern: /^read$/i, meta: { icon: FileText, category: 'file', label: 'Read file' } },
  { pattern: /^write$/i, meta: { icon: FilePlus, category: 'file', label: 'Write file' } },
  { pattern: /^edit$/i, meta: { icon: FileEdit, category: 'file', label: 'Edit file' } },
  { pattern: /^create.*file/i, meta: { icon: FilePlus, category: 'file', label: 'Create file' } },
  { pattern: /^delete.*file/i, meta: { icon: FileText, category: 'file', label: 'Delete file' } },
  { pattern: /^file.*/i, meta: { icon: FileText, category: 'file', label: 'File operation' } },

  // Shell/Command
  { pattern: /^bash$/i, meta: { icon: Terminal, category: 'shell', label: 'Run command' } },
  { pattern: /^shell$/i, meta: { icon: Terminal, category: 'shell', label: 'Shell' } },
  { pattern: /^execute$/i, meta: { icon: Terminal, category: 'shell', label: 'Execute' } },
  { pattern: /^run/i, meta: { icon: Terminal, category: 'shell', label: 'Run' } },

  // Search
  { pattern: /^grep$/i, meta: { icon: Search, category: 'search', label: 'Search in files' } },
  { pattern: /^find$/i, meta: { icon: Search, category: 'search', label: 'Find' } },
  { pattern: /^search$/i, meta: { icon: Search, category: 'search', label: 'Search' } },
  { pattern: /^glob$/i, meta: { icon: FolderOpen, category: 'search', label: 'Find files' } },

  // Browser
  { pattern: /^browser/i, meta: { icon: Globe, category: 'browser', label: 'Browser' } },
  { pattern: /^navigate$/i, meta: { icon: Globe, category: 'browser', label: 'Navigate' } },
  { pattern: /^click$/i, meta: { icon: Globe, category: 'browser', label: 'Click' } },
  { pattern: /^screenshot$/i, meta: { icon: Image, category: 'browser', label: 'Screenshot' } },

  // Communication
  { pattern: /^mail$/i, meta: { icon: Mail, category: 'communication', label: 'Email' } },
  { pattern: /^email$/i, meta: { icon: Mail, category: 'communication', label: 'Email' } },
  { pattern: /^calendar$/i, meta: { icon: Calendar, category: 'communication', label: 'Calendar' } },
  { pattern: /^slack$/i, meta: { icon: MessageSquare, category: 'communication', label: 'Slack' } },

  // Data
  { pattern: /^database$/i, meta: { icon: Database, category: 'data', label: 'Database' } },
  { pattern: /^query$/i, meta: { icon: Database, category: 'data', label: 'Query' } },

  // Utility
  { pattern: /^todo/i, meta: { icon: Wrench, category: 'utility', label: 'Todo' } },
  { pattern: /^code.*analy/i, meta: { icon: Code, category: 'utility', label: 'Analyze code' } },
];

/**
 * Get tool metadata (icon, category, label) from tool name
 */
export function getToolMeta(toolName: string): ToolMeta {
  for (const { pattern, meta } of toolPatterns) {
    if (pattern.test(toolName)) {
      return meta;
    }
  }

  // Default fallback
  return {
    icon: Wrench,
    category: 'unknown',
    label: formatToolLabel(toolName),
  };
}

/**
 * Format tool name into a readable label
 */
function formatToolLabel(toolName: string): string {
  // Convert camelCase/PascalCase to spaces
  const spaced = toolName
    .replace(/([a-z])([A-Z])/g, '$1 $2')
    .replace(/([A-Z]+)([A-Z][a-z])/g, '$1 $2');

  // Capitalize first letter
  return spaced.charAt(0).toUpperCase() + spaced.slice(1);
}

/**
 * Get category color classes
 */
export function getCategoryColor(category: ToolCategory): {
  bg: string;
  text: string;
  border: string;
} {
  switch (category) {
    case 'file':
      return {
        bg: 'bg-blue-50',
        text: 'text-blue-600',
        border: 'border-blue-200',
      };
    case 'shell':
      return {
        bg: 'bg-zinc-100',
        text: 'text-zinc-700',
        border: 'border-zinc-300',
      };
    case 'search':
      return {
        bg: 'bg-purple-50',
        text: 'text-purple-600',
        border: 'border-purple-200',
      };
    case 'browser':
      return {
        bg: 'bg-cyan-50',
        text: 'text-cyan-600',
        border: 'border-cyan-200',
      };
    case 'communication':
      return {
        bg: 'bg-orange-50',
        text: 'text-orange-600',
        border: 'border-orange-200',
      };
    case 'data':
      return {
        bg: 'bg-indigo-50',
        text: 'text-indigo-600',
        border: 'border-indigo-200',
      };
    case 'utility':
      return {
        bg: 'bg-zinc-50',
        text: 'text-zinc-600',
        border: 'border-zinc-200',
      };
    default:
      return {
        bg: 'bg-zinc-50',
        text: 'text-zinc-600',
        border: 'border-zinc-200',
      };
  }
}

/**
 * InlineToolCall - Displays tool execution with status and expandable result
 *
 * Features:
 * - Status indicators (running/success/error) with colors and animations
 * - Tool-specific icons based on category
 * - Collapsible result section
 * - Smooth animations via framer-motion
 */
import { useState } from 'react';
import { motion, AnimatePresence } from 'framer-motion';
import { ChevronRight, CheckCircle, XCircle, Loader2 } from 'lucide-react';
import type { InlineToolCall as InlineToolCallType } from '@normie/types';
import { getToolMeta, getCategoryColor } from '@/lib/tool-icons';
import { formatToolPreview } from '@normie/utils';

interface InlineToolCallProps {
  toolCall: InlineToolCallType;
}

export function InlineToolCall({ toolCall }: InlineToolCallProps) {
  const [isExpanded, setIsExpanded] = useState(toolCall.status === 'running');

  const { name, input, status, result } = toolCall;
  const meta = getToolMeta(name);
  const categoryColor = getCategoryColor(meta.category);
  const preview = formatToolPreview(input);

  const Icon = meta.icon;
  const StatusIcon = status === 'running' ? Loader2 : 
                     status === 'success' ? CheckCircle : XCircle;

  // Status-specific styles
  const statusStyles = {
    running: {
      container: 'border-amber-300 bg-amber-50/50',
      badge: 'bg-amber-500 text-white',
      icon: 'text-amber-500 animate-spin',
    },
    success: {
      container: 'border-emerald-300 bg-emerald-50/50',
      badge: 'bg-emerald-500 text-white',
      icon: 'text-emerald-500',
    },
    error: {
      container: 'border-red-300 bg-red-50/50',
      badge: 'bg-red-500 text-white',
      icon: 'text-red-500',
    },
  };

  const styles = statusStyles[status];

  // Format result for display
  const resultText = typeof result === 'string' 
    ? result 
    : result !== undefined 
      ? JSON.stringify(result, null, 2) 
      : null;

  return (
    <motion.div
      initial={{ opacity: 0, y: 8 }}
      animate={{ opacity: 1, y: 0 }}
      transition={{ duration: 0.2, ease: [0.16, 1, 0.3, 1] }}
      className={`border rounded-xl overflow-hidden ${styles.container}`}
    >
      {/* Header - always visible */}
      <button
        onClick={() => setIsExpanded(!isExpanded)}
        className="flex items-center gap-3 px-4 py-3 w-full hover:bg-black/[0.02] transition-colors text-left"
      >
        {/* Expand arrow */}
        <ChevronRight
          className={`w-4 h-4 text-zinc-400 transition-transform duration-200 ${
            isExpanded ? 'rotate-90' : ''
          }`}
          strokeWidth={1.5}
        />

        {/* Tool icon with category color */}
        <div className={`p-1.5 rounded-lg ${categoryColor.bg}`}>
          <Icon className={`w-4 h-4 ${categoryColor.text}`} strokeWidth={1.5} />
        </div>

        {/* Tool label and name */}
        <div className="flex-1 min-w-0">
          <div className="flex items-center gap-2">
            <span className="text-sm font-medium text-zinc-900">
              {meta.label}
            </span>
            <span className={`text-xs px-2 py-0.5 rounded-full ${styles.badge}`}>
              {name}
            </span>
          </div>
          {preview && (
            <p className="text-xs text-zinc-500 mt-0.5 truncate">
              {preview}
            </p>
          )}
        </div>

        {/* Status icon */}
        <StatusIcon 
          className={`w-5 h-5 ${styles.icon}`} 
          strokeWidth={1.5}
        />
      </button>

      {/* Expandable result section */}
      <AnimatePresence initial={false}>
        {isExpanded && resultText && (
          <motion.div
            initial={{ height: 0, opacity: 0 }}
            animate={{ height: 'auto', opacity: 1 }}
            exit={{ height: 0, opacity: 0 }}
            transition={{ duration: 0.2, ease: [0.16, 1, 0.3, 1] }}
            className="overflow-hidden"
          >
            <div className="px-4 pb-4 pt-2 border-t border-zinc-200/50">
              <p className="text-xs font-medium text-zinc-500 mb-2">Result</p>
              <pre className="text-xs font-mono text-zinc-700 bg-zinc-100 rounded-lg p-3 overflow-x-auto max-h-60 overflow-y-auto">
                {resultText.length > 2000 
                  ? resultText.substring(0, 2000) + '\n... (truncated)'
                  : resultText
                }
              </pre>
            </div>
          </motion.div>
        )}
      </AnimatePresence>

      {/* Running state - show pulsing indicator */}
      {status === 'running' && !isExpanded && (
        <div className="px-4 pb-3">
          <div className="flex items-center gap-2 text-amber-600">
            <div className="w-1.5 h-1.5 bg-amber-500 rounded-full animate-pulse" />
            <span className="text-xs font-light">Running...</span>
          </div>
        </div>
      )}
    </motion.div>
  );
}

  if (hours < 24) return `${hours}h ago`;
  if (days < 7) return `${days}d ago`;
  return new Date(timestamp).toLocaleDateString();
}

// Format tool preview
export function formatToolPreview(toolInput: Record<string, unknown>): string {
  if (!toolInput || typeof toolInput !== 'object') {
    return String(toolInput || '').substring(0, 50);
  }

  const keys = Object.keys(toolInput);
  if (keys.length === 0) return '';

  const previewKeys = ['pattern', 'command', 'file_path', 'path', 'query', 'content', 'description'];
  const key = previewKeys.find(k => toolInput[k] !== undefined) || keys[0];
  const value = toolInput[key];

  if (typeof value === 'string') {
    return `${key}: ${value.substring(0, 50)}${value.length > 50 ? '...' : ''}`;
  } else if (Array.isArray(value)) {
    return `${key}: [${value.length} items]`;
  } else if (typeof value === 'object' && value !== null) {
    return `${key}: {...}`;
  }
  return `${key}: ${String(value).substring(0, 30)}`;
}

// Extract browser URL from text
export function extractBrowserUrl(text: string): { url: string; sessionId: string } | null {
  const regex = /https:\/\/live\.anchorbrowser\.io\?sessionId=([a-f0-9-]+)/i;
  const match = text.match(regex);
  if (match) {
    return { url: match[0], sessionId: match[1] };
  }
  return null;
}

