/**
 * InlineToolCall - Displays tool execution with status and expandable result
 *
 * Features:
 * - Status indicators (running/success/error) with animated ping for running
 * - Tool-specific icons based on category
 * - Collapsible result section
 * - Smooth animations via framer-motion
 */
import { useState } from 'react';
import { motion, AnimatePresence } from 'framer-motion';
import { ChevronRight, CheckCircle, XCircle } from 'lucide-react';
import type { InlineToolCall as InlineToolCallType } from '@normie/types';
import { getToolMeta, getCategoryColor } from '@/lib/tool-icons';
import { formatToolPreview } from '@normie/utils';

interface InlineToolCallProps {
  toolCall: InlineToolCallType;
}

export function InlineToolCall({ toolCall }: InlineToolCallProps) {
  const [isExpanded, setIsExpanded] = useState(toolCall.status === 'running');

  const { name, input, status, result } = toolCall;
  const meta = getToolMeta(name);
  const categoryColor = getCategoryColor(meta.category);
  const preview = formatToolPreview(name, input);

  const Icon = meta.icon;

  // Status-specific styles
  const statusStyles = {
    running: {
      container: 'border-amber-200 bg-amber-50/30',
      indicator: (
        <span className="flex items-center gap-1.5">
          <span className="relative flex h-2 w-2">
            <span className="animate-ping absolute inline-flex h-full w-full rounded-full bg-amber-400 opacity-75"></span>
            <span className="relative inline-flex rounded-full h-2 w-2 bg-amber-500"></span>
          </span>
          <span className="text-xs text-amber-600 font-medium">Running</span>
        </span>
      ),
    },
    success: {
      container: 'border-emerald-200 bg-emerald-50/30',
      indicator: (
        <span className="flex items-center gap-1 text-emerald-600">
          <CheckCircle className="w-3.5 h-3.5" />
          <span className="text-xs font-medium">Done</span>
        </span>
      ),
    },
    error: {
      container: 'border-red-200 bg-red-50/30',
      indicator: (
        <span className="flex items-center gap-1 text-red-600">
          <XCircle className="w-3.5 h-3.5" />
          <span className="text-xs font-medium">Error</span>
        </span>
      ),
    },
  };

  const styles = statusStyles[status];

  // Format result for display
  const resultText =
    typeof result === 'string'
      ? result
      : result !== undefined
        ? JSON.stringify(result, null, 2)
        : null;

  return (
    <motion.div
      initial={{ opacity: 0, y: 8 }}
      animate={{ opacity: 1, y: 0 }}
      transition={{ duration: 0.2, ease: [0.16, 1, 0.3, 1] }}
      className={`rounded-lg border shadow-sm transition-colors ${styles.container}`}
    >
      {/* Header */}
      <button
        onClick={() => setIsExpanded(!isExpanded)}
        className="flex items-center gap-3 px-3 py-2.5 w-full hover:bg-black/[0.02] transition-colors text-left"
      >
        {/* Icon with category color */}
        <div className={`p-1.5 rounded-md ${categoryColor.bg} ${categoryColor.border} border`}>
          <Icon className={`w-3.5 h-3.5 ${categoryColor.text}`} strokeWidth={1.5} />
        </div>

        {/* Label and preview */}
        <div className="flex-1 min-w-0">
          <div className="flex items-center gap-2">
            <span className="text-sm font-medium text-zinc-800">{meta.label}</span>
            {styles.indicator}
          </div>

          {preview && (
            <p className="text-xs text-zinc-500 mt-0.5 truncate font-mono">
              {preview}
            </p>
          )}
        </div>

        {/* Expand arrow */}
        <ChevronRight
          className={`w-4 h-4 text-zinc-400 transition-transform duration-200 ${isExpanded ? 'rotate-90' : ''}`}
          strokeWidth={1.5}
        />
      </button>

      {/* Result section */}
      <AnimatePresence initial={false}>
        {isExpanded && resultText && (
          <motion.div
            initial={{ height: 0, opacity: 0 }}
            animate={{ height: 'auto', opacity: 1 }}
            exit={{ height: 0, opacity: 0 }}
            transition={{ duration: 0.2, ease: [0.16, 1, 0.3, 1] }}
            className="overflow-hidden"
          >
            <div className="px-3 pb-3 pt-2 border-t border-zinc-100">
              <p className="text-xs font-medium text-zinc-400 mb-1.5">Result</p>
              <pre className="text-xs font-mono text-zinc-600 bg-white rounded-md p-2.5 border border-zinc-100 overflow-x-auto max-h-48 overflow-y-auto">
                {resultText.length > 2000
                  ? resultText.substring(0, 2000) + '\n... (truncated)'
                  : resultText}
              </pre>
            </div>
          </motion.div>
        )}
      </AnimatePresence>

      {/* Running state - show hint to expand */}
      {status === 'running' && !isExpanded && !resultText && (
        <div className="px-3 pb-2.5 pt-1">
          <div className="flex items-center gap-2 text-amber-600/70">
            <span className="text-xs font-light">Click to see progress</span>
          </div>
        </div>
      )}
    </motion.div>
  );
}

