/**
 * Raw API message response shape
 */
interface ApiMessageResponse {
  id?: string | number;
  role: string;
  content: string;
  reasoning?: string;
  toolCalls?: ToolCall[];
  inlineToolCalls?: ToolCall[];
  metadata?: {
    inlineToolCalls?: ToolCall[];
    [key: string]: unknown;
  };
}

/**
 * Transform API message to local Message type
 */
function transformApiMessage(msg: ApiMessageResponse): Message {
  // Extract inlineToolCalls from either top-level (streaming) or metadata (stored)
  const inlineToolCalls = msg.inlineToolCalls || msg.metadata?.inlineToolCalls;

  return {
    id: msg.id ? String(msg.id) : generateId(),
    role: msg.role === 'user' ? 'user' : 'assistant',
    content: msg.content || '',
    reasoning: msg.reasoning,
    toolCalls: msg.toolCalls,
    inlineToolCalls: inlineToolCalls && inlineToolCalls.length > 0 
      ? inlineToolCalls 
      : undefined,
  };
}

